import type { PrereqNode } from "../types";

/**
 * Turns BYU-Idaho's catalogue requisite prose into `PrereqNode` expressions.
 *
 * Phase 2 of opening the app to every program. 136 courses were hand-audited;
 * a few thousand cannot be, so the and/or shape has to be derived mechanically
 * — and the parser has to know when it is out of its depth, because a wrong
 * prerequisite that claims to be verified is the worst failure this codebase
 * has (DATA_GAPS U9).
 *
 * The prose is machine-generated by Kuali and far more regular than it looks:
 * a flat list of `•` bullets where certain phrases are *headers* that declare a
 * combinator, and the bullets after them are that group's members. Indentation
 * is not preserved, so nesting is inferred from the header vocabulary alone —
 * which is closed and small. Every header this parser does not recognise
 * lowers confidence rather than being silently ignored.
 */

export type ParseConfidence = "exact" | "parsed" | "unsure";

export interface ParsedRequisites {
  prereq: PrereqNode;
  coreq: PrereqNode;
  confidence: ParseConfidence;
  /**
   * Things the catalogue named that did not make it into the expression —
   * test scores, retired courses, courses outside the harvested set. Kept so a
   * human can see exactly what was discarded.
   */
  dropped: string[];
  /** Why the confidence is not `exact`. */
  notes: string[];
}

/** Requisite-bearing fields, in every casing the API actually uses (U9). */
export const REQUISITE_FIELDS = [
  "prerequisites",
  "preRequisites",
  "coRequisites",
  "corequisites",
  "courseRequirements",
  "courseRequirementText",
] as const;

export type RequisiteField = (typeof REQUISITE_FIELDS)[number];

/** Placement/entrance tests read like course codes ("SAT 540") but are not. */
const NOT_SUBJECTS = new Set([
  "ACT", "SAT", "SATR", "TOEFL", "IELTS", "ALEKS", "LUC", "CLEP", "AP",
]);

const COURSE_RE = /^([A-Z]{2,6})\s?(\d{3}[A-Za-z]?)\b/;

export function plainText(html: unknown): string {
  if (typeof html !== "string") return "";
  return html
    .replace(/<!--.*?-->/g, "")
    .replace(/<li[^>]*>/g, " • ")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();
}

type Combinator = "and" | "or";

interface Header {
  combinator: Combinator;
  /** True when the phrasing allows the same semester ("concurrently enrolled"). */
  coreq: boolean;
  /** Arity of an "N of the following" header. 1 means a plain OR. */
  n: number;
}

/**
 * The closed header vocabulary, in the order it must be tested.
 *
 * "Completed or concurrently enrolled" decides coreq-ness, **not** the field
 * the text arrived in: several courses state a corequisite inside
 * `prerequisites` and vice versa, and enforcing a coreq as a prereq is
 * DATA_GAPS U10.
 */
const HEADERS: { re: RegExp; make: (m: RegExpMatchArray) => Header }[] = [
  {
    re: /^completed or concurrently enrolled in at least (\d+) of the following/i,
    make: (m) => ({ combinator: "or", coreq: true, n: Number(m[1]) }),
  },
  {
    re: /^completed or concurrently enrolled in/i,
    make: () => ({ combinator: "and", coreq: true, n: 0 }),
  },
  {
    re: /^(?:take|complete) (\d+) of the following/i,
    make: (m) => ({ combinator: "or", coreq: false, n: Number(m[1]) }),
  },
  {
    re: /^take the following course/i,
    make: () => ({ combinator: "and", coreq: false, n: 0 }),
  },
  {
    re: /^complete all of the following/i,
    make: () => ({ combinator: "and", coreq: false, n: 0 }),
  },
];

function headerFor(segment: string): Header | null {
  for (const h of HEADERS) {
    const m = segment.match(h.re);
    if (m) return h.make(m);
  }
  return null;
}

/** A course code at the start of a bullet, normalised to fixture form. */
function courseCodeOf(segment: string): string | null {
  const body = segment.replace(/^-?or-?\s*/i, "").trim();
  const m = body.match(COURSE_RE);
  if (!m || NOT_SUBJECTS.has(m[1])) return null;
  // "CS101 (last offered 2023)" — a retired alternative, not a live edge.
  if (/last offered/i.test(body)) return null;
  return (m[1] + m[2]).toUpperCase();
}

interface Group {
  header: Header;
  items: string[];
  /** Named by the catalogue but not usable — kept for the audit trail. */
  dropped: string[];
}

function toNode(items: string[], combinator: Combinator): PrereqNode {
  if (items.length === 0) return null;
  if (items.length === 1) return items[0];
  return combinator === "and" ? { and: items } : { or: items };
}

function combine(nodes: PrereqNode[], combinator: Combinator = "and"): PrereqNode {
  const real = nodes.filter((n) => n !== null);
  if (real.length === 0) return null;
  if (real.length === 1) return real[0];
  return combinator === "and" ? { and: real } : { or: real };
}

/**
 * Canonical form, so two spellings of the same requirement compare equal.
 *
 * Two rewrites, both of which are plain logic rather than convenience:
 *  - a group of one **is** its member (`{and:[X]}` ≡ `X`) — the hand-written
 *    fixture wraps some single courses in a group for readability;
 *  - AND nested in AND flattens, and OR in OR likewise (associativity). The
 *    parser builds right-leaning trees from a bullet list while a human writes
 *    them flat; `(A AND (B AND C))` and `(A AND B AND C)` are the same rule.
 */
export function normalizeNode(n: PrereqNode): PrereqNode {
  if (n === null || typeof n === "string") return n;
  const isAnd = "and" in n;
  const kids: PrereqNode[] = [];
  for (const raw of isAnd ? n.and : n.or) {
    const k = normalizeNode(raw);
    if (k === null) continue;
    // Same combinator one level down: absorb its children.
    if (typeof k === "object" && isAnd === "and" in k) {
      kids.push(...("and" in k ? k.and : k.or));
    } else {
      kids.push(k);
    }
  }
  if (kids.length === 0) return null;
  if (kids.length === 1) return kids[0];
  return isAnd ? { and: kids } : { or: kids };
}

/**
 * Parse one course's requisite fields.
 *
 * `resolve` maps a catalogue code to the id actually used by the data set, or
 * null when it is not carried. It returns an id rather than a boolean because
 * the catalogue's casing is not the fixture's — `CSE121C` in the prose is
 * `CSE121c` in `courses.json`, and matching case-sensitively silently dropped
 * a live prerequisite branch from two ECEN courses.
 *
 * A code the catalogue names but we do not carry is *dropped and recorded* —
 * never invented — and dropping is what separates `exact` from `parsed`.
 */
export function parseRequisites(
  fields: Partial<Record<RequisiteField, unknown>>,
  resolve: (code: string) => string | null,
): ParsedRequisites {
  const notes: string[] = [];
  const dropped: string[] = [];
  const groups: Group[] = [];

  for (const field of REQUISITE_FIELDS) {
    const text = plainText(fields[field]);
    if (!text) continue;

    // The field name is only a *default*: phrasing wins, so a corequisite
    // stated inside `prerequisites` is still treated as a corequisite.
    const fieldIsCoreq = field === "coRequisites" || field === "corequisites";
    let current: Group | null = null;

    for (const raw of text.split("•")) {
      const segment = raw.trim();
      if (!segment) continue;

      const header = headerFor(segment);
      if (header) {
        if (header.n > 1) {
          notes.push(
            `"${segment.slice(0, 60)}" needs ${header.n} of a list; PrereqNode cannot express that`,
          );
        }
        current = { header, items: [], dropped: [] };
        groups.push(current);
        continue;
      }

      const code = courseCodeOf(segment);
      if (!code) {
        // A non-course condition: a test score, an authorisation, a laptop.
        dropped.push(segment.slice(0, 80));
        if (current) current.dropped.push(segment.slice(0, 80));
        continue;
      }
      const id = resolve(code);
      if (!id) {
        dropped.push(code);
        if (current) current.dropped.push(code);
        continue;
      }

      if (!current) {
        // Bullets before any header: an implicit "all of these".
        current = {
          header: { combinator: "and", coreq: fieldIsCoreq, n: 0 },
          items: [],
          dropped: [],
        };
        groups.push(current);
      }
      current.items.push(id);
    }
  }

  /**
   * Nesting. Kuali emits a flat bullet list, but a header with **no items of
   * its own** followed by more headers is a *container* whose children are
   * those groups — "Complete 1 of the following / Take the following
   * course(s): A, B / Take the following course(s): C, D" means (A AND B) OR
   * (C AND D), not A AND B AND C AND D. Reading it flat turned CSE 450's four
   * alternative routes into one impossible conjunction, and reported `exact`
   * while doing it.
   */
  let container: Header | null = null;
  if (groups.length > 1 && groups[0].items.length === 0) {
    container = groups.shift()!.header;
  }

  const preNodes: PrereqNode[] = [];
  const coNodes: PrereqNode[] = [];
  let unsure = groups.some((g) => g.header.n > 1) || (container?.n ?? 0) > 1;

  for (const g of groups) {
    const node = toNode(g.items, g.header.combinator);
    if (node === null) {
      // A group whose every option was dropped is a requirement we cannot see.
      // Silently emitting nothing would read as "no prerequisite".
      if (g.dropped.length) {
        unsure = true;
        notes.push(
          `a whole ${g.header.combinator.toUpperCase()} group was dropped: ${g.dropped.join(", ")}`,
        );
      }
      continue;
    }
    (g.header.coreq ? coNodes : preNodes).push(node);
  }

  const join: Combinator = container?.combinator ?? "and";
  // An OR container whose children straddle prereq and coreq has no honest
  // representation in two separate trees — say so rather than pick one.
  if (join === "or" && preNodes.length > 0 && coNodes.length > 0) {
    unsure = true;
    notes.push("an OR container mixes prerequisites and corequisites");
  }

  const confidence: ParseConfidence = unsure
    ? "unsure"
    : dropped.length
      ? "parsed"
      : "exact";

  return {
    prereq: combine(preNodes, join),
    coreq: combine(coNodes, join),
    confidence,
    dropped: [...new Set(dropped)],
    notes,
  };
}

/** Structural equality for two expressions, order-insensitive within a group. */
export function sameNode(rawA: PrereqNode, rawB: PrereqNode): boolean {
  const a = normalizeNode(rawA);
  const b = normalizeNode(rawB);
  if (a === null || b === null) return a === b;
  if (typeof a === "string" || typeof b === "string") return a === b;
  const aAnd = "and" in a;
  const bAnd = "and" in b;
  if (aAnd !== bAnd) return false;
  const ax = aAnd ? a.and : (a as { or: PrereqNode[] }).or;
  const bx = bAnd ? b.and : (b as { or: PrereqNode[] }).or;
  if (ax.length !== bx.length) return false;
  const rest = [...bx];
  return ax.every((x) => {
    const i = rest.findIndex((y) => sameNode(x, y));
    if (i < 0) return false;
    rest.splice(i, 1);
    return true;
  });
}
